queries.sparql:
SELECT DISTINCT ?person ?birthDate ?sitelinks ?article WHERE {
  VALUES ?occupation { wd:Q33999 }
  ?person wdt:P31 wd:Q5; wdt:P106 ?occupation; wdt:P569 ?birthDate; wikibase:sitelinks ?sitelinks.
  ?article schema:about ?person; schema:isPartOf <https://en.wikipedia.org/>.
  FILTER(?birthDate >= "1950-01-01T00:00:00Z"^^xsd:dateTime)
  FILTER(?birthDate < "1989-01-01T00:00:00Z"^^xsd:dateTime)
  FILTER(?sitelinks >= 20)
} ORDER BY DESC(?sitelinks) ?person LIMIT 120

